//! Constant-product AMM pair analogue for the Vegeta S3 Uniswap-V2-like family.
use cosmwasm_std::{entry_point,to_json_binary,Binary,Deps,DepsMut,Env,MessageInfo,Response,StdError,StdResult,Uint128};use cw_storage_plus::{Item,Map};use schemars::JsonSchema;use serde::{Deserialize,Serialize};use thiserror::Error;
#[derive(Serialize,Deserialize,Clone,Debug,PartialEq,Eq,JsonSchema)]pub struct InstantiateMsg{pub asset0:String,pub asset1:String}
#[derive(Serialize,Deserialize,Clone,Debug,PartialEq,Eq,JsonSchema)]#[serde(rename_all="snake_case")]pub enum ExecuteMsg{Swap{offer_index:u8,amount_in:Uint128,min_out:Uint128,recipient:String},MintLiquidity{provider:String,amount0:Uint128,amount1:Uint128},BurnLiquidity{provider:String,liquidity:Uint128},Sync{reserve0:Uint128,reserve1:Uint128}}
#[derive(Serialize,Deserialize,Clone,Debug,PartialEq,Eq,JsonSchema)]#[serde(rename_all="snake_case")]pub enum QueryMsg{GetReserves{},LpBalance{address:String},Token0{},Token1{}}
#[derive(Serialize,Deserialize,Clone,Debug,PartialEq,Eq,JsonSchema)]pub struct Config{pub asset0:String,pub asset1:String}
#[derive(Serialize,Deserialize,Clone,Debug,PartialEq,Eq,JsonSchema)]pub struct Reserves{pub reserve0:Uint128,pub reserve1:Uint128}
#[derive(Serialize,Deserialize,Clone,Debug,PartialEq,Eq,JsonSchema)]pub struct AmountResponse{pub amount:Uint128}
const CONFIG:Item<Config>=Item::new("config");const RESERVES:Item<Reserves>=Item::new("reserves");const TOTAL_LP:Item<Uint128>=Item::new("total_lp");const LP_BALANCES:Map<&str,Uint128>=Map::new("lp_balances");
#[derive(Error,Debug,PartialEq)]pub enum ContractError{#[error("{0}")]Std(#[from]StdError),#[error("invalid asset index")]InvalidAsset,#[error("slippage")]Slippage,#[error("insufficient liquidity")]InsufficientLiquidity}
#[entry_point]pub fn instantiate(deps:DepsMut,_:Env,_:MessageInfo,msg:InstantiateMsg)->Result<Response,ContractError>{CONFIG.save(deps.storage,&Config{asset0:msg.asset0,asset1:msg.asset1})?;RESERVES.save(deps.storage,&Reserves{reserve0:Uint128::zero(),reserve1:Uint128::zero()})?;TOTAL_LP.save(deps.storage,&Uint128::zero())?;Ok(Response::new())}
#[entry_point]pub fn execute(deps:DepsMut,_:Env,_:MessageInfo,msg:ExecuteMsg)->Result<Response,ContractError>{match msg{ExecuteMsg::Swap{offer_index,amount_in,min_out,recipient}=>swap(deps,offer_index,amount_in,min_out,recipient),ExecuteMsg::MintLiquidity{provider,amount0,amount1}=>mint(deps,provider,amount0,amount1),ExecuteMsg::BurnLiquidity{provider,liquidity}=>burn(deps,provider,liquidity),ExecuteMsg::Sync{reserve0,reserve1}=>{RESERVES.save(deps.storage,&Reserves{reserve0,reserve1})?;Ok(Response::new())}}}
fn swap(deps:DepsMut,offer_index:u8,amount_in:Uint128,min_out:Uint128,_recipient:String)->Result<Response,ContractError>{let mut r=RESERVES.load(deps.storage)?;let (rin,rout)=match offer_index{0=>(r.reserve0,r.reserve1),1=>(r.reserve1,r.reserve0),_=>return Err(ContractError::InvalidAsset)};let amount_with_fee=amount_in.multiply_ratio(997u128,1000u128);let numerator=amount_with_fee.checked_mul(rout).map_err(StdError::overflow)?;let denominator=rin.checked_add(amount_with_fee).map_err(StdError::overflow)?;let out=if denominator.is_zero(){Uint128::zero()}else{numerator/denominator};if out<min_out{return Err(ContractError::Slippage)};if offer_index==0{r.reserve0=r.reserve0.checked_add(amount_in).map_err(StdError::overflow)?;r.reserve1=r.reserve1.checked_sub(out).map_err(StdError::overflow)?;}else{r.reserve1=r.reserve1.checked_add(amount_in).map_err(StdError::overflow)?;r.reserve0=r.reserve0.checked_sub(out).map_err(StdError::overflow)?;}RESERVES.save(deps.storage,&r)?;Ok(Response::new().add_attribute("amount_out",out.to_string()))}
fn mint(deps:DepsMut,provider:String,a0:Uint128,a1:Uint128)->Result<Response,ContractError>{let p=deps.api.addr_validate(&provider)?;let minted=Uint128::new(integer_sqrt(a0.u128().saturating_mul(a1.u128())));let mut r=RESERVES.load(deps.storage)?;r.reserve0=r.reserve0.checked_add(a0).map_err(StdError::overflow)?;r.reserve1=r.reserve1.checked_add(a1).map_err(StdError::overflow)?;RESERVES.save(deps.storage,&r)?;TOTAL_LP.update(deps.storage,|x|x.checked_add(minted).map_err(StdError::overflow))?;LP_BALANCES.update(deps.storage,p.as_str(),|x|->StdResult<_>{Ok(x.unwrap_or_default().checked_add(minted).map_err(StdError::overflow)?)})?;Ok(Response::new())}
fn burn(deps:DepsMut,provider:String,liq:Uint128)->Result<Response,ContractError>{let p=deps.api.addr_validate(&provider)?;let total=TOTAL_LP.load(deps.storage)?;let bal=LP_BALANCES.may_load(deps.storage,p.as_str())?.unwrap_or_default();if liq>bal||liq>total{return Err(ContractError::InsufficientLiquidity)};let mut r=RESERVES.load(deps.storage)?;let out0=r.reserve0.multiply_ratio(liq.u128(),total.u128());let out1=r.reserve1.multiply_ratio(liq.u128(),total.u128());r.reserve0=r.reserve0.checked_sub(out0).map_err(StdError::overflow)?;r.reserve1=r.reserve1.checked_sub(out1).map_err(StdError::overflow)?;RESERVES.save(deps.storage,&r)?;LP_BALANCES.save(deps.storage,p.as_str(),&bal.checked_sub(liq).map_err(StdError::overflow)?)?;TOTAL_LP.save(deps.storage,&total.checked_sub(liq).map_err(StdError::overflow)?)?;Ok(Response::new())}
fn integer_sqrt(n:u128)->u128{if n<2{return n}let mut x=n;let mut y=(x+n/x)/2;while y<x{x=y;y=(x+n/x)/2;}x}
#[entry_point]pub fn query(deps:Deps,_:Env,msg:QueryMsg)->StdResult<Binary>{match msg{QueryMsg::GetReserves{}=>to_json_binary(&RESERVES.load(deps.storage)?),QueryMsg::LpBalance{address}=>to_json_binary(&AmountResponse{amount:LP_BALANCES.may_load(deps.storage,&address)?.unwrap_or_default()}),QueryMsg::Token0{}=>to_json_binary(&CONFIG.load(deps.storage)?.asset0),QueryMsg::Token1{}=>to_json_binary(&CONFIG.load(deps.storage)?.asset1)}}
#[cfg(test)]mod tests{use super::*;use cosmwasm_std::testing::{mock_dependencies,mock_env,mock_info};#[test]fn swap_changes_singleton_reserves(){let mut d=mock_dependencies();instantiate(d.as_mut(),mock_env(),mock_info("x",&[]),InstantiateMsg{asset0:"a".into(),asset1:"b".into()}).unwrap();execute(d.as_mut(),mock_env(),mock_info("x",&[]),ExecuteMsg::Sync{reserve0:Uint128::new(1000),reserve1:Uint128::new(1000)}).unwrap();execute(d.as_mut(),mock_env(),mock_info("x",&[]),ExecuteMsg::Swap{offer_index:0,amount_in:Uint128::new(100),min_out:Uint128::new(1),recipient:"alice".into()}).unwrap();let r=RESERVES.load(d.as_ref().storage).unwrap();assert!(r.reserve0>Uint128::new(1000)&&r.reserve1<Uint128::new(1000));}}
